<?php
declare(strict_types=1);
require dirname(__DIR__).'/app/bootstrap.php';
$checks=0;function check(bool $v,string $label):void{global $checks;if(!$v)throw new RuntimeException($label);$checks++;echo 'PASS '.$label.PHP_EOL;}
$m=Namira\Pwa::manifest();check($m['id']==='/'&&$m['scope']==='/'&&$m['start_url']==='/','installed app uses existing public root');check($m['lang']==='fa'&&$m['dir']==='rtl'&&$m['display']==='standalone','Persian standalone manifest');
