$page='home';ob_start();view('pwa-head',compact('page'));$head=ob_get_clean();check(str_contains($head,'icon-96.png')&&str_contains($head,'apple-touch-icon'),'public head exposes search and Apple icons');check(str_contains($head,'pwa-manifest'),'manifest is linked from public pages');$page='admin';ob_start();view('pwa-head',compact('page'));$admin=ob_get_clean();check(!str_contains($admin,'pwa.js')&&!str_contains($admin,'pwa-manifest'),'admin layout does not install public worker');check(!str_contains(file_get_contents(BASE_PATH.'/public/robots.txt'),'Disallow: /assets'),'robots allows icon crawling');
$code='<?php require '.var_export(BASE_PATH.'/app/bootstrap.php',true).';putenv("DB_DSN=invalid:no-database");$_GET["page"]="pwa-manifest";$_SERVER["REQUEST_METHOD"]="GET";$_SERVER["REQUEST_URI"]="/index.php?page=pwa-manifest";Namira\\Web::run();';$tmp=tempnam(sys_get_temp_dir(),'namira-pwa-');file_put_contents($tmp,$code);$proc=proc_open([PHP_BINARY,$tmp],[1=>['pipe','w'],2=>['pipe','w']],$pipes);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);$exit=proc_close($proc);unlink($tmp);check($exit===0&&json_decode($out,true)===$m,'public manifest serves without database or login');check($err==='','public metadata has no PHP warnings');
